from typing import List

class Solution:
    def lastVisitedIntegers(self, words: List[str]) -> List[int]:
        ov = []
        ans = []
        ci = -1
        i = 0

        while i < len(words):
            s = words[i]
            if s == 'prev':
                if ci == -1:
                    ans.append(-1)
                else:
                    ans.append(ov[ci])
                ci -= 1
            else:
                vv = 0
                while len(s) > 0:
                    c = s[0]
                    vv = vv * 10 + int(c)
                    s = s[1:]
                ci = len(ov)
                ov.append(vv)
            i += 1

        return ans

